const items = $input.all();
const results = [];

function cleanStr(v) {
  return (v === undefined || v === null) ? '' : v.toString().trim();
}

for (const item of items) {
  const data = item.json.body || item.json;

  const fullName = cleanStr(data['Full Name'] || data.fullName || data.name);
  const email    = cleanStr(data['Email'] || data.email).toLowerCase();
  const phone    = cleanStr(data['Phone'] || data.phone);
  const company  = cleanStr(data['Company'] || data.company);
  const service  = cleanStr(data['Service Required'] || data.service || data.serviceRequired);
  const budget   = cleanStr(data['Budget'] || data.budget);
  const message  = cleanStr(data['Message'] || data.message);

  const missingFields = [];
  if (!fullName) missingFields.push('Full Name');
  if (!email)    missingFields.push('Email');
  if (!phone)    missingFields.push('Phone');
  if (!company)  missingFields.push('Company');
  if (!service)  missingFields.push('Service Required');
  if (!message)  missingFields.push('Message');

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (email && !emailRegex.test(email)) {
    missingFields.push('Valid Email Format');
  }

  const isValid = missingFields.length === 0;

  // Unique Lead ID: LEAD-<timestamp>-<random 5 chars>
  const leadId = `LEAD-${Date.now()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;
  const dateReceived = new Date().toISOString();

  results.push({
    json: {
      leadId,
      dateReceived,
      isValid,
      missingFields,
      fullName,
      email,
      phone,
      company,
      serviceRequired: service,
      budget,
      message
    }
  });
}

return results;

