const items = $input.all();
const leadItems = $('Validate & Clean Lead Data').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const aiResponse = items[i].json;
  const lead = leadItems[i] ? leadItems[i].json : {};

  let analysis = {
    category: 'Uncategorized',
    intent: 'Unknown',
    leadQuality: 'Warm',
    priority: 5,
    summary: 'AI analysis unavailable - manual review required.',
    recommendedAction: 'Manually review this lead.'
  };

  try {
    const rawContent = aiResponse.choices[0].message.content;
    const parsed = JSON.parse(rawContent);

    analysis.category = parsed.category || analysis.category;
    analysis.intent = parsed.intent || analysis.intent;

    const quality = (parsed.leadQuality || '').toString().trim();
    analysis.leadQuality = ['Hot', 'Warm', 'Cold'].includes(quality) ? quality : analysis.leadQuality;

    const priorityNum = parseInt(parsed.priority, 10);
    analysis.priority = (!isNaN(priorityNum) && priorityNum >= 1 && priorityNum <= 10) ? priorityNum : analysis.priority;

    analysis.summary = parsed.summary || analysis.summary;
    analysis.recommendedAction = parsed.recommendedAction || analysis.recommendedAction;
  } catch (err) {
    // Fall back to default "Warm / needs manual review" analysis defined above.
    // This guarantees the workflow keeps moving even if the AI response is malformed.
  }

  results.push({
    json: {
      ...lead,
      category: analysis.category,
      intent: analysis.intent,
      leadQuality: analysis.leadQuality,
      priority: analysis.priority,
      aiSummary: analysis.summary,
      recommendedAction: analysis.recommendedAction,
      status: 'Processed'
    }
  });
}

return results;

const item = $input.first().json;

const daysMap = { Hot: 1, Warm: 3, Cold: 7 };
const days = daysMap[item.leadQuality] !== undefined ? daysMap[item.leadQuality] : 3;

const followUpDate = new Date();
followUpDate.setDate(followUpDate.getDate() + days);

return [{
  json: {
    ...item,
    followUpDays: days,
    followUpDate: followUpDate.toISOString(),
    followUpStatus: 'Pending'
  }
}];

const errorData = $input.first().json;

const failedNode = errorData.execution && errorData.execution.lastNodeExecuted
  ? errorData.execution.lastNodeExecuted
  : (errorData.trigger && errorData.trigger.lastNodeExecuted) || 'Unknown node';

const errorMessage = errorData.execution && errorData.execution.error && errorData.execution.error.message
  ? errorData.execution.error.message
  : JSON.stringify(errorData).slice(0, 500);

return [{
  json: {
    leadId: 'UNKNOWN - see execution log',
    timestamp: new Date().toISOString(),
    status: 'Failed',
    failedNode: failedNode,
    errorMessage: errorMessage
  }
}];
